alternative.example:
type A = { x: f64 }
type B = { x: f64 }            // A と同じ型
type Node = { label: String, children: Array<Node> }   // 再帰: 名前で区別

fn leaf() -> Node { { label: "a", children: [] } }    // Rec と Node を、Node を 1 段だけ展開して単一化する
fn f(r: B) -> f64 { r.x }
fn g(r: A) -> f64 { f(r) }     // 通る

